const maxOrdinal = `-- name: MaxOrdinal :one
SELECT COALESCE(MAX(ordinal), -1) AS max_ordinal
FROM role_instances
WHERE component_id = ? AND role = ?
`

type MaxOrdinalParams struct {
	ComponentID int64
	Role        string
}

// Returns -1 when the role has no instances, so the first one gets 0.
// Do NOT use count(): ordinals may have holes and count() would collide
// with an already-used number. See ADR-0028.
func (q *Queries) MaxOrdinal(ctx context.Context, arg MaxOrdinalParams) (interface{}, error) {
	row := q.db.QueryRowContext(ctx, maxOrdinal, arg.ComponentID, arg.Role)
	var max_ordinal interface{}
	err := row.Scan(&max_ordinal)
	return max_ordinal, err
}

const putSecret = `-- name: PutSecret :one
INSERT INTO secrets (component_id, param, version, ciphertext, created_at, updated_at)
VALUES (?, ?, 1, ?, ?, ?)
ON CONFLICT (component_id, param) DO UPDATE SET
    version    = secrets.version + 1,
    ciphertext = excluded.ciphertext,
    updated_at = excluded.updated_at
RETURNING id, component_id, param, version, ciphertext, created_at, updated_at
`

type PutSecretParams struct {
	ComponentID int64
	Param       string
	Ciphertext  []byte
	CreatedAt   string
	UpdatedAt   string
}

// First write stores version=1; rotation bumps it. The version participates
// in the spec digest, so rotation necessarily produces a new generation.
// See docs/design/16-secrets.md section 5.
func (q *Queries) PutSecret(ctx context.Context, arg PutSecretParams) (Secret, error) {
	row := q.db.QueryRowContext(ctx, putSecret,
		arg.ComponentID,
		arg.Param,
		arg.Ciphertext,
		arg.CreatedAt,
		arg.UpdatedAt,
	)
	var i Secret
	err := row.Scan(
		&i.ID,
		&i.ComponentID,
		&i.Param,
		&i.Version,
		&i.Ciphertext,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

