const startComponentRemoval = `-- name: StartComponentRemoval :exec
UPDATE components
SET state = ?,
    removal_keep_config = ?, removal_purge_data = ?, removal_purge_user = ?,
    removing_at = ?, updated_at = ?
WHERE id = ?
`

type StartComponentRemovalParams struct {
	State             string
	RemovalKeepConfig int64
	RemovalPurgeData  int64
	RemovalPurgeUser  int64
	RemovingAt        string
	UpdatedAt         string
	ID                int64
}

// Writes the lifecycle state and the three switches in one statement; see
// the Go wrapper for why they must not be written separately.
//
// The state is a bound parameter, not a literal: sqlc 1.31 STRIPS THE QUOTES
// off a string literal on the right-hand side of an UPDATE ... SET, turning
// SET state = removing into SET state = removing -- a column reference.
// It exits 0 while doing this. The failure only shows up at runtime as
// "no such column: removing".
func (q *Queries) StartComponentRemoval(ctx context.Context, arg StartComponentRemovalParams) error {
	_, err := q.db.ExecContext(ctx, startComponentRemoval,
		arg.State,
		arg.RemovalKeepConfig,
		arg.RemovalPurgeData,
		arg.RemovalPurgeUser,
		arg.RemovingAt,
		arg.UpdatedAt,
		arg.ID,
	)
	return err
}

